/**
 * Local row types for the Marketer's tables (migration 20261011130000_staff_marketer.sql).
 * database.types.ts is regenerated by the lead after the Phase 2 merge; until then these are
 * the source of truth and queries use the `Db = any` cast (as sms-agent does).
 */

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type Db = any;

export type CampaignKind = "win_back" | "seasonal" | "custom";
export type CampaignStatus = "draft" | "awaiting_owner" | "approved" | "sending" | "done" | "cancelled";
export type RecipientStatus = "queued" | "sending" | "sent" | "skipped" | "failed";
export type ReplyStatus = "new" | "awaiting_owner" | "approved" | "posted" | "rejected" | "expired" | "skipped" | "failed";
export type PostTopic = "offer" | "seasonal_tip" | "job_highlight";
export type PostStatus = "draft" | "awaiting_owner" | "approved" | "rejected" | "expired" | "failed";

export interface SendWindow {
  perHour: number;
  startHour: number;
  endHour: number;
  /** 0 = Sunday … 6 = Saturday. */
  days: number[];
  weeklyCap: number;
}

export interface MarketingCampaignRow {
  id: string;
  organization_id: string;
  company_id: string;
  kind: CampaignKind;
  status: CampaignStatus;
  audience_filter: Record<string, unknown>;
  message: string | null;
  audience_count: number;
  sent_count: number;
  skipped_count: number;
  failed_count: number;
  approval_id: string | null;
  send_window: Partial<SendWindow> | null;
  scheduled_for: string | null;
  period_key: string | null;
  created_by: string;
  cancel_reason: string | null;
  approved_at: string | null;
  started_at: string | null;
  completed_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface CampaignRecipientRow {
  id: string;
  organization_id: string;
  company_id: string;
  campaign_id: string;
  contact_id: string;
  status: RecipientStatus;
  reason: string | null;
  last_purchase_at: string | null;
  message_log_id: string | null;
  provider_ref: string | null;
  claimed_at: string | null;
  sent_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface GoogleReviewRow {
  id: string;
  organization_id: string;
  company_id: string;
  review_name: string;
  rating: number | null;
  text: string | null;
  author_name: string | null;
  published_at: string | null;
  google_maps_uri: string | null;
  reply_draft: string | null;
  reply_status: ReplyStatus;
  approval_id: string | null;
  owner_alerted_at: string | null;
  owner_texted_at: string | null;
  text_pruned_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface GooglePostDraftRow {
  id: string;
  organization_id: string;
  company_id: string;
  week_start: string;
  topic: PostTopic;
  body: string | null;
  status: PostStatus;
  approval_id: string | null;
  owner_texted_at: string | null;
  created_at: string;
  updated_at: string;
}
